query JobBoardList($boardId: String!) {
    oatsExternalJobPostings(boardId: $boardId) {
      jobPostings {
        id
        extId
        title
        locations {
          id
          name
          city
          isoCountry
          isRemote
          extId
        }
        job {
          id
          department {
            id
            name
            extId
          }
          locationType
          employmentType
        }
      }
    }
    oatsExternalJobPostingsFilters(boardId: $boardId) {
      type
      displayName
      rawValue
      value
      count
    }
    jobBoardExternal(vanityUrlPath: $boardId) {
      id
      teamDisplayName
      descriptionHtml
      pageTitle
    }
  }

fragment PublicQuestionFragment on PublicOatsQuestion {
    extId
    answerType
    displayType
    fileType
    text
    description
    isRequired
    options {
      extId
      value
    }
    numericRatingRange
  }

fragment PublicDemographicQuestionFragment on PublicOatsDemographicSurveyQuestion {
    extId
    answerType
    displayType
    text
    description
    options {
      extId
      value
    }
  }

query ExternalJobPosting($boardId: String!, $extId: String!) {
    oatsExternalJobPosting(boardId: $boardId, extId: $extId) {
      id
      title
      descriptionHtml
      extId
      startDateTs
      firstPublishedTsSec
      companyLogo
      companyUrl
      isApplicationFormHidden
      applicationFormTemplate {
        id
        includeEeoc
        eeocConfig {
          includeRaceXGender
          includeVeteranStatus
          includeDisabilityStatus
        }
      }
      isUnlistedExternally
      locations {
        id
        extId
        name
        city
        isoCountry
        isRemote
      }
      job {
        id
        locationType
        employmentType
        requisitionId
        teamDisplayName
        department {
          id
          extId
          name
        }
        locations {
          id
          extId
          name
          city
          isoCountry
          isRemote
        }
      }
      jobPostSectionHtml {
        introHtml
        outroHtml
      }
      compensationHtml
    }
    oatsJobPostFieldsAndQuestions(
      jobBoardVanityPath: $boardId
      jobPostExtId: $extId
    ) {
      fields {
        fieldType
        isRequired
      }
      questions {
        ...PublicQuestionFragment
      }
      demographicSurvey {
        extId
        surveyType
        questions {
          ...PublicDemographicQuestionFragment
        }
      }
    }
  }

